import{_ as t,c as o,o as e,ag as i}from"./chunks/framework.DQvKz0xt.js";const c=JSON.parse('{"title":"布局动画 (Animation) - Rive 编辑器","description":"布局 (Layouts) 通过向布局容器添加动画，你可以定义内容在重新排版 (Reflow) 时的插值方式。当布局容器调整大小时，其子元素可能需要改变位置。添加布局动画可以让子元素的重排随时间平滑过渡，并配合你选择的缓动曲线。","frontmatter":{"title":"布局动画 (Animation) - Rive 编辑器","description":"布局 (Layouts) 通过向布局容器添加动画，你可以定义内容在重新排版 (Reflow) 时的插值方式。当布局容器调整大小时，其子元素可能需要改变位置。添加布局动画可以让子元素的重排随时间平滑过渡，并配合你选择的缓动曲线。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 布局, 布局动画"}]]},"headers":[],"relativePath":"editor/layouts/layout-animation.md","filePath":"editor/layouts/layout-animation.md","lastUpdated":1774838907000}'),n={name:"editor/layouts/layout-animation.md"};function r(l,a,s,d,p,u){return e(),o("div",null,[...a[0]||(a[0]=[i('<p>布局 (Layouts)</p><h1 id="布局动画-animation" tabindex="-1">布局动画 (Animation) <a class="header-anchor" href="#布局动画-animation" aria-label="Permalink to &quot;布局动画 (Animation)&quot;">​</a></h1><p>通过向布局容器添加动画，你可以定义内容在重新排版 (Reflow) 时的插值方式。当布局容器调整大小时，其子元素可能需要改变位置。添加布局动画可以让子元素的重排随时间平滑过渡，并配合你选择的缓动曲线。</p><h2 id="​-添加布局动画" tabindex="-1"><a href="#adding-layout-animation">​</a> 添加布局动画 <a class="header-anchor" href="#​-添加布局动画" aria-label="Permalink to &quot;[​](#adding-layout-animation) 添加布局动画&quot;">​</a></h2><p>首先选中一个布局组件，点击检查器中 <code>Layout Animation</code> 旁的 <code>+</code> 按钮。通常建议在父布局上进行设置。</p><p>接下来，从 3 种模式中选择：</p><ul><li><strong>无 (None)</strong>：不使用动画。</li><li><strong>继承 (Inherit)</strong>：从父布局继承动画参数。</li><li><strong>自定义 (Custom)</strong>：为选中的布局定义独立的动画参数。</li></ul><p>选择自定义选项后，你可以设置持续时间 (Duration) 和插值类型 (Interpolation)，类似于状态机的过渡设置。所有插值类型（除了三次方插值）均受支持。</p><p><a href="https://help.rive.app/editor/layouts/layout-styles" target="_blank" rel="noreferrer">样式 (Styles)</a><a href="/docs/editor/layouts/n-slicing">N轴切片 (N-Slicing)</a></p>',9)])])}const _=t(n,[["render",r]]);export{c as __pageData,_ as default};
